steps.command:
set -e; install -d -m 700 /app/kube-session-spool /app/kube-session-upload /app/kube-session-events; cat > /app/kube_disconnect_harness.py <<'PY'
from pathlib import Path
import hashlib,json,os,subprocess,sys,time
ROOT=Path('/app'); SPOOL=ROOT/'kube-session-spool'; UPLOAD=ROOT/'kube-session-upload'; EVENTS=ROOT/'kube-session-events/events.jsonl'
def event(session,kind):
 with EVENTS.open('a') as f: f.write(json.dumps({'session':session,'type':kind},separators=(',',':'))+'\n')
def digest(path): return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def control():
 sid='read-control-42'; proc=subprocess.Popen(['sh','-c','echo role=viewer; sleep 0.2; echo result=complete'],stdout=subprocess.PIPE,stderr=subprocess.STDOUT); print(f'session={sid} process_pid={proc.pid}',flush=True); out,_=proc.communicate(timeout=5); part=SPOOL/(sid+'.part'); part.write_bytes(out); part.chmod(0o600); event(sid,'session.start'); event(sid,'session.data'); final=UPLOAD/(sid+'.session'); part.rename(final); event(sid,'session.end'); print(f'session={sid} process_exit={proc.returncode} uploaded={final} sha256={digest(final)}',flush=True)
def disconnected():
 sid='kube-root-42'; proc=subprocess.Popen(['sh','-c','echo uid=0-root-gid=0-root; exec sleep 300'],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True); first=proc.stdout.readline(); part=SPOOL/(sid+'.part'); part.write_text('kubectl exec deploy/payments -- sh\n'+first); part.chmod(0o600); event(sid,'session.start'); event(sid,'session.data'); (ROOT/'kube-root-42.pid').write_text(str(proc.pid)+'\n'); print(f'session={sid} process_pid={proc.pid} request_context=context-canceled transcript_sha256={digest(part)}',flush=True)
if sys.argv[1]=='control': control()
elif sys.argv[1]=='disconnect': disconnected()
PY
chmod 700 /app/kube_disconnect_harness.py; stat -c '%n mode=%a' /app/kube-session-spool /app/kube-session-upload /app/kube-session-events /app/kube_disconnect_harness.py
